customCss:
.dual-quote-strip {
      display: grid;
      grid-template-columns: 72px minmax(0, 1fr) 72px;
      gap: 1rem;
      align-items: center;
      margin: 1.5rem 0;
    }

    .side-totem {
      margin: 0;
      min-height: 320px;
      border-radius: 18px;
      overflow: hidden;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.04);
    }

    .side-totem img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .side-totem-placeholder {
      display: none;
      height: 100%;
      min-height: 320px;
      padding: 0.75rem 0.5rem;
      align-items: center;
      justify-content: center;
      text-align: center;
      font-size: 0.82rem;
      line-height: 1.35;
      color: rgba(0, 0, 0, 0.68);
      background: linear-gradient(180deg, rgba(210, 210, 210, 0.18), rgba(180, 180, 180, 0.1));
    }

    .quote-core {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 0;
      background: transparent;
      border: 0;
    }

    .quote-core .note-quote {
      margin: 0;
      width: 100%;
      max-width: 320px;
      text-align: center;
      padding: 1.25rem 1rem;
      border-radius: 18px;
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.08);
      backdrop-filter: blur(2px);
    }

    .quote-core .note-quote p:last-child {
      margin-bottom: 0;
    }

    @media (max-width: 720px) {
      .dual-quote-strip {
        grid-template-columns: 1fr;
      }

      .side-totem {
        min-height: 180px;
      }

      .side-totem-placeholder {
        min-height: 180px;
      }
    }
